import { decode } from "light-bolt11-decoder";
var RECEIVER_IDENTITY_PUBLIC_KEY_SHORT_CHANNEL_ID = "f42400f424000001";
var PAYMENT_HASH_NAME = "payment_hash";
var AMOUNT_MSATS_NAME = "amount";
var PAYMENT_SECRET_NAME = "payment_secret";
function decodeInvoice(invoice) {
  const decodedInvoice = decode(invoice);
  const network = getNetworkFromInvoice(invoice);
  if (network === null) {
    throw new ValidationError("Invalid network found in invoice: " + invoice);
  }
  let paymentSection;
  let routeHints = [];
  let amountSection;
  let paymentSecretSection;
  let fallbackAddress;
  for (const section of decodedInvoice.sections) {
    if (section.name === PAYMENT_HASH_NAME) {
      paymentSection = section;
    }
    if (section.name === AMOUNT_MSATS_NAME) {
      amountSection = section;
    }
    if (section.name === PAYMENT_SECRET_NAME) {
      paymentSecretSection = section;
    }
  }
  routeHints = decodedInvoice.route_hints;
  const amountMSats = amountSection?.value ? BigInt(amountSection.value) : null;
  const paymentHash = paymentSection?.value;
  for (const routeHintArray of routeHints) {
    for (const routeHint of routeHintArray) {
      if (routeHint.short_channel_id === RECEIVER_IDENTITY_PUBLIC_KEY_SHORT_CHANNEL_ID) {
        fallbackAddress = routeHint.pubkey;
      }
    }
  }
  if (paymentHash === void 0) {
    throw new ValidationError("No payment hash found in invoice: " + invoice);
  }
  if (paymentSecretSection?.value === void 0) {
    throw new ValidationError(
      "Invalid payment secret found in invoice: " + invoice
    );
  }
  return { amountMSats, fallbackAddress, paymentHash };
}
function getNetworkFromInvoice(invoice) {
  if (invoice.startsWith("lnbcrt")) return 3 /* REGTEST */;
  if (invoice.startsWith("lnbc")) return 0 /* MAINNET */;
  if (invoice.startsWith("lntb")) return 1 /* TESTNET */;
  if (invoice.startsWith("lnsb")) return 2 /* SIGNET */;
  return null;
}
function isValidSparkFallback(bytes) {
  if (bytes.length !== 33) {
    return false;
  }
  return true;
}

// src/services/lightning.ts
var LightningService = class {
  config;
  connectionManager;
  signingService;
  constructor(config, connectionManager, signingService) {
    this.config = config;
    this.connectionManager = connectionManager;
    this.signingService = signingService;
  }
  async createLightningInvoice({
    invoiceCreator,
    amountSats,
    memo,
    receiverIdentityPubkey,
    descriptionHash
  }) {
    const crypto = getCrypto();
    const randBytes = crypto.getRandomValues(new Uint8Array(32));
    const preimage = numberToBytesBE3(
      bytesToNumberBE4(randBytes) % secp256k15.CURVE.n,
      32
    );
    return await this.createLightningInvoiceWithPreImage({
      invoiceCreator,
      amountSats,
      memo,
      preimage,
      receiverIdentityPubkey,
      descriptionHash
    });
  }
  async createLightningInvoiceWithPreImage({
    invoiceCreator,
    amountSats,
    memo,
    preimage,
    receiverIdentityPubkey,
    descriptionHash
  }) {
    const paymentHash = sha2566(preimage);
    const invoice = await invoiceCreator(
      amountSats,
      paymentHash,
      memo,
      receiverIdentityPubkey,
      descriptionHash
    );
    if (!invoice) {
      throw new ValidationError("Failed to create lightning invoice", {
        field: "invoice",
        value: null,
        expected: "Non-null invoice"
      });
    }
    const shares = await this.config.signer.splitSecretWithProofs({
      secret: preimage,
      curveOrder: secp256k15.CURVE.n,
      threshold: this.config.getThreshold(),
      numShares: Object.keys(this.config.getSigningOperators()).length
    });
    const errors = [];
    const promises = Object.entries(this.config.getSigningOperators()).map(
      async ([_, operator]) => {
        const share = shares[operator.id];
        if (!share) {
          throw new ValidationError("Share not found for operator", {
            field: "share",
            value: operator.id,
            expected: "Non-null share"
          });
        }
        const sparkClient = await this.connectionManager.createSparkClient(
          operator.address
        );
        const userIdentityPublicKey = receiverIdentityPubkey ? hexToBytes6(receiverIdentityPubkey) : await this.config.signer.getIdentityPublicKey();
        try {
          await sparkClient.store_preimage_share({
            paymentHash,
            preimageShare: {
              secretShare: numberToBytesBE3(share.share, 32),
              proofs: share.proofs
            },
            threshold: this.config.getThreshold(),
            invoiceString: invoice.invoice.encodedInvoice,
            userIdentityPublicKey
          });
        } catch (e) {
          errors.push(e);
        }
      }
    );
    await Promise.all(promises);
    if (errors.length > 0) {
      throw new NetworkError(
        "Failed to store preimage shares",
        {
          operation: "store_preimage_share",
          errorCount: errors.length,
          errors: errors.map((e) => e.message).join(", ")
        },
        errors[0]
      );
    }
    return invoice;
  }
  async swapNodesForPreimage({
    leaves,
    receiverIdentityPubkey,
    paymentHash,
    invoiceString,
    isInboundPayment,
    feeSats = 0,
    amountSatsToSend
  }) {
    const sparkClient = await this.connectionManager.createSparkClient(
      this.config.getCoordinatorAddress()
    );
    let signingCommitments;
    try {
      signingCommitments = await sparkClient.get_signing_commitments({
        nodeIds: leaves.map((leaf) => leaf.leaf.id)
      });
    } catch (error) {
      throw new NetworkError(
        "Failed to get signing commitments",
        {
          operation: "get_signing_commitments",
          errorCount: 1,
          errors: error instanceof Error ? error.message : String(error)
        },
        error
      );
    }
    const leafSigningJobs = await this.signingService.signRefunds(
      leaves,
      signingCommitments.signingCommitments,
      receiverIdentityPubkey
    );
    const transferId = uuidv74();
    let bolt11String = "";
    let amountSats = 0;
    if (invoiceString) {
      const decodedInvoice = decodeInvoice(invoiceString);
      let amountMsats = 0;
      try {
        amountMsats = Number(decodedInvoice.amountMSats);
      } catch (error) {
        console.error("Error decoding invoice", error);
      }
      const isZeroAmountInvoice = !amountMsats;
      if (isZeroAmountInvoice && amountSatsToSend === void 0) {
        throw new ValidationError(
          "Invalid amount. User must specify amountSatsToSend for 0 amount lightning invoice",
          {
            field: "amountSatsToSend",
            value: amountSatsToSend,
            expected: "positive number"
          }
        );
      }
      amountSats = isZeroAmountInvoice ? amountSatsToSend : amountMsats / 1e3;
      if (isNaN(amountSats) || amountSats <= 0) {
        throw new ValidationError("Invalid amount", {
          field: "amountSats",
          value: amountSats,
          expected: "greater than 0"
        });
      }
      bolt11String = invoiceString;
    }
    const reason = isInboundPayment ? 1 /* REASON_RECEIVE */ : 0 /* REASON_SEND */;
    let response;
    try {
      response = await sparkClient.initiate_preimage_swap({
        paymentHash,
        invoiceAmount: {
          invoiceAmountProof: {
            bolt11Invoice: bolt11String
          },
          valueSats: amountSats
        },
        reason,
        transfer: {
          transferId,
          ownerIdentityPublicKey: await this.config.signer.getIdentityPublicKey(),
          leavesToSend: leafSigningJobs,
          receiverIdentityPublicKey: receiverIdentityPubkey,
          expiryTime: new Date(Date.now() + 2 * 60 * 1e3)
        },
        receiverIdentityPublicKey: receiverIdentityPubkey,
        feeSats
      });
    } catch (error) {
      throw new NetworkError(
        "Failed to initiate preimage swap",
        {
          operation: "initiate_preimage_swap",
          errorCount: 1,
          errors: error instanceof Error ? error.message : String(error)
        },
        error
      );
    }
    return response;
  }
  async queryUserSignedRefunds(paymentHash) {
    const sparkClient = await this.connectionManager.createSparkClient(
      this.config.getCoordinatorAddress()
    );
    let response;
    try {
      response = await sparkClient.query_user_signed_refunds({
        paymentHash,
        identityPublicKey: await this.config.signer.getIdentityPublicKey()
      });
    } catch (error) {
      throw new NetworkError(
        "Failed to query user signed refunds",
        {
          operation: "query_user_signed_refunds",
          errorCount: 1,
          errors: error instanceof Error ? error.message : String(error)
        },
        error
      );
    }
    return response.userSignedRefunds;
  }
  validateUserSignedRefund(userSignedRefund) {
    const refundTx = getTxFromRawTxBytes(userSignedRefund.refundTx);
    return refundTx.getOutput(0).amount || 0n;
  }
  async providePreimage(preimage) {
    const sparkClient = await this.connectionManager.createSparkClient(
      this.config.getCoordinatorAddress()
    );
    const paymentHash = sha2566(preimage);
    let response;
    try {
      response = await sparkClient.provide_preimage({
        preimage,
        paymentHash,
        identityPublicKey: await this.config.signer.getIdentityPublicKey()
      });
    } catch (error) {
      throw new NetworkError(
        "Failed to provide preimage",
        {
          operation: "provide_preimage",
          errorCount: 1,
          errors: error instanceof Error ? error.message : String(error)
        },
        error
      );
    }
    if (!response.transfer) {
      throw new ValidationError("No transfer returned from coordinator", {
        field: "transfer",
        value: response,
        expected: "Non-null transfer"
      });
    }
    return response.transfer;
  }
};

